patch:
diff --git a/recreate/no-var-use-before-declaration.js b/recreate/no-var-use-before-declaration.js
new file mode 100644
index 0000000..1c7712f
--- /dev/null
+++ b/recreate/no-var-use-before-declaration.js
@@ -0,0 +1,53 @@
+/*
+ * Check for the reported no-var bug: the autofix turns `var o` into `let o`
+ * while `o` is read earlier in the function, which throws a ReferenceError.
+ *
+ * Usage (from the repo root):
+ *   node recreate/no-var-use-before-declaration.js [path-to-eslint-package-dir]
+ *
+ * Exits 1 if the autofixed code throws a ReferenceError (bug present), else 0.
+ * With no argument it checks the eslint in this checkout.
+ */
+"use strict";
+
+const path = require("node:path");
+
+const eslintDir = path.resolve(process.argv[2] || ".");
+const { Linter } = require(path.join(eslintDir, "lib", "api"));
+const { version } = require(path.join(eslintDir, "package.json"));
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`;
+
+const linter = new Linter();
+const result = linter.verifyAndFix(
+	code,
+	[{ rules: { "no-var": ["error"] } }],
+	"a.js",
+);
+
+console.log(`eslint ${version}: fixed=${result.fixed}`);
+console.log(result.output);
+
+let error = null;
+
+try {
+	const fn = new Function(
+		"console",
+		`${result.output.replace(/^export /u, "")}\nreturn a;`,
+	)({ log() {} });
+
+	fn();
+} catch (e) {
+	error = e;
+}
+
+if (error instanceof ReferenceError) {
+	console.log(`BUG PRESENT: fixed code throws ${error.name}: ${error.message}`);
+	process.exitCode = 1;
+} else {
+	console.log("OK: fixed code runs without a ReferenceError");
+}
